-- Run this in the Supabase SQL Editor to create the required tables for Hawas Agent.

-- 1. User Table
CREATE TABLE IF NOT EXISTS "User" (
    "telegramId" TEXT PRIMARY KEY,
    "carvId" TEXT,
    "evmAddress" TEXT,
    "isAdmin" BOOLEAN DEFAULT FALSE,
    "lang" TEXT DEFAULT 'ar',
    "lastInteractedAt" TIMESTAMP WITH TIME ZONE
);

-- 2. GroupSettings Table
CREATE TABLE IF NOT EXISTS "GroupSettings" (
    "chatId" TEXT PRIMARY KEY,
    "mode" TEXT DEFAULT 'chatty',
    "lang" TEXT DEFAULT 'ar'
);

-- 3. Knowledge Table
CREATE TABLE IF NOT EXISTS "Knowledge" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "question" TEXT,
    "answer" TEXT,
    "tags" TEXT, -- JSON string array
    "confidence" DOUBLE PRECISION DEFAULT 1.0,
    "isTentative" BOOLEAN DEFAULT FALSE,
    "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "updatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Indices for better search performance
CREATE INDEX IF NOT EXISTS "idx_knowledge_question" ON "Knowledge" ("question");
CREATE INDEX IF NOT EXISTS "idx_knowledge_tags" ON "Knowledge" ("tags");

-- IMPORTANT: You may need to disable RLS (Row Level Security) 
-- OR create policies to allow 'anon' role to write if using SUPABASE_KEY (anon).
